<?php
 namespace QQWorld\Framework\App; class ActionFlag { protected $_request; protected $_flags = []; public function __construct(\QQWorld\Framework\App\RequestInterface $request) { $this->_request = $request; } public function set($action, $flag, $value) { if ('' === $action) { $action = $this->_request->getActionName(); } $this->_flags[$this->_getControllerKey()][$action][$flag] = $value; } public function get($action, $flag = '') { if ('' === $action) { $action = $this->_request->getActionName(); } if ('' === $flag) { return isset( $this->_flags[$this->_getControllerKey()] ) ? $this->_flags[$this->_getControllerKey()] : []; } elseif (isset($this->_flags[$this->_getControllerKey()][$action][$flag])) { return $this->_flags[$this->_getControllerKey()][$action][$flag]; } else { return false; } } protected function _getControllerKey() { return $this->_request->getRouteName() . '_' . $this->_request->getControllerName(); } } 